registerModuleVariants("cultivator.digest.blob.early", [{ when: {}, weight: 6, text: ["Her belly hangs a little heavier; the notebook is already out. The living space fills on purpose. Digestion begins as quiet work.","The chair takes more of her as she logs the result. Foundations settle under her. She stays focused inward."] }]);
registerModuleVariants("cultivator.digest.blob.late", [{ when: {}, weight: 6, text: ["The chair takes more of her as she logs the result. Supports stay strengthened. She regards that as correct housing.","Flour still on her knuckles, she writes the transfer down. Visitors get the calm clinical look. She is finished and satisfied."] }]);
